const toast=document.querySelector('[role="status"]');let timer;function notify(message){if(!toast)return;toast.textContent=message;clearTimeout(timer);timer=setTimeout(()=>toast.textContent='',3500)}document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy);notify('Copied '+button.dataset.copy)}catch{notify(button.dataset.copy)}}));document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>document.querySelector(button.dataset.jump)?.scrollIntoView({behavior:'smooth'})));document.querySelector('[data-year]').textContent=new Date().getFullYear();